<script setup lang="ts">
import GlassPlanner from './GlassPlanner.vue'
import { newId } from "../id"
import { ElMessage } from 'element-plus'
import { computed, watch } from 'vue'
import { Plus, Trash2, Scissors, Download, Printer } from 'lucide-vue-next'
import { useWorkshop } from '../store'
import { mm, money, T } from '../types'
import LengthInput from './LengthInput.vue'
import { download, csv } from '../export'
const s=useWorkshop()
const printPlan=()=>window.print()
const keys=computed(()=>[...new Set([...Object.values(s.project!.profiles).map(p=>p.stock_key),...s.stocks.map(p=>p.stock_key)])])
const required=computed(()=>[...new Set(s.geometry!.parts.map(p=>p.stock_key))])
const missing=computed(()=>required.value.filter(key=>!s.stocks.some(stock=>stock.stock_key===key)))
const unavailable=computed(()=>required.value.filter(key=>s.stocks.some(stock=>stock.stock_key===key)&&!s.stocks.some(stock=>stock.stock_key===key&&stock.available!==0)))
function describe(key:string){const names=[...new Set(s.geometry!.parts.filter(p=>p.stock_key===key).map(p=>p.category_label))];return names.length?`${names.join(' / ')}（${key}）`:key}
function supplement(){
  const additions=missing.value.map(key=>({id:'示例-'+newId(),stock_key:key,length:6000*T,price_cents:0,available:null}))
  s.stocks.push(...additions);s.error='';s.invalidate();s.persist()
  ElMessage.success(`已补充 ${additions.length} 种型号，请核对示例长度 6000 mm 并填写实际规格`)
}
watch([()=>s.stocks,()=>s.settings],()=>{s.invalidate();s.persist()},{deep:true})
function add(){s.stocks.push({id:newId(),stock_key:missing.value[0]??keys.value[0]!,length:6000*T,price_cents:0,available:null})}
function exportPlan(){if(s.plan)download(`${s.project!.name}-切割方案.json`,JSON.stringify({project:s.project,stocks:s.stocks,settings:s.settings,result:s.plan},null,2))}
function exportCuts(){if(s.plan)download(`${s.project!.name}-逐根切割.csv`,csv([['原料根号','型号','规格mm','次序','构件实例','类别','长边mm','短边mm','角度','毛坯区间起mm','毛坯区间止mm','前锯缝mm','后锯缝mm'],...s.plan.groups.flatMap(g=>g.bars.flatMap(b=>b.pieces.map((p,i)=>[b.id,b.stock_key,mm(b.length),i+1,p.instance,p.category,mm(p.length),mm(p.short_length),p.angle,mm(p.from_tick),mm(p.to_tick),mm(p.front_loss),mm(p.back_loss)])))]),'text/csv;charset=utf-8')}
</script>
<template><div class="cutting-view"><div v-if="missing.length||unavailable.length" class="panel no-print"><el-alert type="warning" :closable="false" title="型材原料规格尚未匹配，玻璃排料不受影响"/><p v-if="missing.length" class="muted">缺少规格：{{missing.map(describe).join('、')}}。窗型型号必须与下方原料型号一致。</p><p v-if="unavailable.length" class="muted">可用数量全为 0：{{unavailable.map(describe).join('、')}}。请按实际库存修改数量；留空表示可采购、不限量。</p><el-button v-if="missing.length" @click="supplement">补充缺失规格（示例长度 6000 mm）</el-button></div><GlassPlanner/><div class="panel-heading no-print"><h2>型材采购与一维切割</h2></div>
<section class="panel stock-panel no-print"><div class="panel-heading"><div><span class="eyebrow">STOCK LIBRARY</span><h2>原料规格</h2></div><el-button @click="add"><Plus :size="15"/> 添加规格</el-button></div>
<p class="muted">同一型号可添加多种长度；只有型号相同的构件才会合并排料。数量留空表示可采购、不限量。</p>
<el-table class="desktop-data" :data="s.stocks" max-height="340" size="small"><el-table-column label="规格编号" width="150"><template #default="{row}"><el-input v-model="row.id" aria-label="原料规格编号"/></template></el-table-column><el-table-column label="原料型号" min-width="180"><template #default="{row}"><el-select v-model="row.stock_key" aria-label="原料型号"><el-option v-for="key in keys" :key="key" :value="key" :label="describe(key)"/></el-select></template></el-table-column><el-table-column label="整料长度" width="160"><template #default="{row}"><LengthInput v-model="row.length" :min="2" label="整料长度"/></template></el-table-column><el-table-column label="单价 / 元" width="150"><template #default="{row}"><el-input-number :model-value="row.price_cents/100" :min="0" :max="100000" :precision="2" :controls="false" @update:model-value="(v:number|undefined)=>row.price_cents=Math.round((v??0)*100)"/></template></el-table-column><el-table-column label="可用根数" width="140"><template #default="{row}"><el-input-number :model-value="row.available" :min="0" :max="500" :precision="0" :controls="false" placeholder="不限" @update:model-value="(v:number|undefined)=>row.available=v??null"/></template></el-table-column><el-table-column width="50"><template #default="{row}"><el-button text type="danger" aria-label="删除原料规格" @click="s.stocks=s.stocks.filter(x=>x!==row)"><Trash2 :size="15"/></el-button></template></el-table-column></el-table>
<div class="mobile-data stock-cards"><article v-for="(row,index) in s.stocks" :key="index" class="mobile-card"><div class="card-title"><b>原料规格 {{index+1}}</b><el-button text type="danger" aria-label="删除原料规格" @click="s.stocks.splice(index,1)"><Trash2 :size="18"/>删除</el-button></div><el-form label-position="top"><el-form-item label="规格编号"><el-input v-model="row.id" aria-label="原料规格编号"/></el-form-item><el-form-item label="原料型号"><el-select v-model="row.stock_key" aria-label="原料型号"><el-option v-for="key in keys" :key="key" :value="key" :label="describe(key)"/></el-select></el-form-item><el-form-item label="整料长度"><LengthInput v-model="row.length" :min="2" label="整料长度"/></el-form-item><div class="two-cols"><el-form-item label="单价 / 元"><el-input-number :model-value="row.price_cents/100" :min="0" :max="100000" :precision="2" :controls="false" @update:model-value="(v:number|undefined)=>row.price_cents=Math.round((v??0)*100)"/></el-form-item><el-form-item label="可用根数"><el-input-number :model-value="row.available" :min="0" :max="500" :precision="0" :controls="false" placeholder="不限" @update:model-value="(v:number|undefined)=>row.available=v??null"/></el-form-item></div></el-form></article></div></section>
<section class="panel no-print"><div class="panel-heading"><div><span class="eyebrow">CUTTING RULES</span><h2>切割工艺与目标</h2></div><el-tag effect="plain">独立双端斜切 · 保守用料</el-tag></div>
<el-form label-position="top" :model="s.settings" class="cut-settings"><el-form-item label="刀片厚度"><LengthInput v-model="s.settings.kerf" label="刀片厚度"/></el-form-item><el-form-item label="每根原料头部修整（含锯缝）"><LengthInput v-model="s.settings.trim_start" label="头部修整"/></el-form-item><el-form-item label="每根原料尾部修整（含锯缝）"><LengthInput v-model="s.settings.trim_end" label="尾部修整"/></el-form-item><el-form-item label="优化目标"><el-select v-model="s.settings.objective"><el-option value="bars" label="最少根数，其次最少购料长度"/><el-option value="cost" label="最低采购金额，其次最少根数"/></el-select></el-form-item><el-form-item label="每个型号求解时限"><el-select v-model="s.settings.time_limit"><el-option v-for="n in [3,10,30]" :key="n" :value="n" :label="`${n} 秒`"/></el-select></el-form-item></el-form>
<div class="rule-note">直切每根预留 1 道锯缝；45° 外框每根预留 2 道斜切锯缝，每道按 √2 × 刀片厚度向上取整。默认不共用斜口、不嵌套尖角。余料单独列出，不作为已购买新料。</div>
<div class="solve-action"><span class="muted">{{s.solving?'正在求解各型号；修改参数会使本次结果失效。':'按当前窗型清单重新计算，全部构件必须完整覆盖。'}}</span><el-button type="primary" size="large" :loading="s.solving" :disabled="s.busy||!!missing.length||!!unavailable.length" @click="s.solve"><Scissors v-if="!s.solving" :size="17"/> 计算采购与切割方案</el-button></div>
</section>
<template v-if="s.plan">
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">CUTTING PLAN</span><h2>采购与切割方案</h2></div><div class="no-print action-row"><el-button @click="exportCuts"><Download :size="15"/>切割 CSV</el-button><el-button @click="exportPlan">完整方案</el-button><el-button @click="printPlan"><Printer :size="15"/>打印</el-button></div></div>
<el-alert :type="s.plan.primary_proven?'success':'warning'" :closable="false" :title="s.plan.primary_proven?'当前工艺与原料约束下，主优化目标已证明最优。':'当前为限时可行方案，尚未证明最优；可以延长时限重算。'"/>
<div class="plan-stats"><div><span>采购数量</span><strong>{{s.plan.bar_count}} <small>根</small></strong></div><div><span>采购金额</span><strong>{{s.stocks.every(x=>x.price_cents>0)?'¥ '+money(s.plan.cost_cents):'价格未完整录入'}}</strong></div><div><span>长度利用率</span><strong>{{(s.plan.total_parts/s.plan.total_stock*100).toFixed(2)}}<small>%</small></strong></div><div><span>剩余料长</span><strong>{{mm(s.plan.total_remnant)}} <small>mm</small></strong></div></div>
<el-table :data="s.plan.purchase" class="purchase-table"><el-table-column prop="stock_key" label="原料型号" min-width="120"/><el-table-column prop="stock_id" label="规格编号" min-width="120"/><el-table-column label="整料长度 / mm" min-width="130"><template #default="{row}">{{mm(row.length)}}</template></el-table-column><el-table-column prop="count" label="采购根数"/><el-table-column label="小计 / 元"><template #default="{row}">{{row.price_cents?money(row.cost_cents):'未录价'}}</template></el-table-column></el-table>
</section>
<section v-for="g in s.plan.groups" :key="g.stock_key" class="panel cut-group"><div class="panel-heading"><h3>{{g.stock_key}} <small>{{g.bars.length}} 根整料</small></h3><el-tag :type="g.primary_proven?'success':'warning'">{{g.primary_proven?'主目标最优':'可行方案'}}</el-tag></div>
<article v-for="(b,i) in g.bars" :key="b.id" class="bar-card"><div class="bar-caption"><strong>{{String(i+1).padStart(2,'0')}} <span>{{b.stock_id}} · {{mm(b.length)}} mm</span></strong><span>{{b.pieces.length}} 件 · 工艺损耗 {{mm(b.loss)}} · 余料 {{mm(b.remnant)}} mm</span></div>
<div class="cut-bar-scroll"><svg class="cut-bar" viewBox="0 0 1000 42" preserveAspectRatio="none" role="img" :aria-label="`${b.id} 切割示意图`"><rect width="1000" height="42" fill="#e9e9e0"/><rect v-if="b.trim_start" :width="b.trim_start/b.length*1000" height="42" fill="#c68b47"/><g v-for="(p,j) in b.pieces" :key="p.instance"><rect :x="p.from_tick/b.length*1000" :width="(p.to_tick-p.from_tick)/b.length*1000" height="42" fill="#c68b47"/><rect :x="p.cut_start/b.length*1000" :width="p.length/b.length*1000" height="42" :fill="j%2?'#54796b':'#31594e'" stroke="white" stroke-width="1"/><text v-if="p.length/b.length>.035" :x="(p.cut_start+p.length/2)/b.length*1000" y="26" text-anchor="middle" fill="white" font-size="12">{{mm(p.length)}}</text></g><rect v-if="b.trim_end" :x="1000-b.trim_end/b.length*1000" :width="b.trim_end/b.length*1000" height="42" fill="#c68b47"/></svg></div>
<div class="cut-sequence"><span v-for="(p,j) in b.pieces" :key="p.instance"><b>{{j+1}}</b> {{p.instance}} · {{mm(p.length)}} mm · {{p.angle}}°</span></div>
<details><summary>查看精确切割区间与锯缝</summary><table class="plain-table"><thead><tr><th>构件实例</th><th>长边／短边</th><th>轴向占用区间</th><th>前／后锯缝</th></tr></thead><tbody><tr v-for="p in b.pieces" :key="p.instance"><td>{{p.instance}}</td><td>{{mm(p.length)}} / {{mm(p.short_length)}}</td><td>{{mm(p.from_tick)}}～{{mm(p.to_tick)}}</td><td>{{mm(p.front_loss)}} / {{mm(p.back_loss)}}</td></tr></tbody></table></details>
</article><p class="muted">绿色：构件长边包络；金色：锯缝及修整；浅灰色：余料。45° 构件按独立毛坯展示，区间不代表锯机靠尺设置。</p></section>
</template>
<section v-else class="empty-plan"><Scissors :size="32"/><h3>把每一根原料，安排得更合适</h3><p>完善原料规格后开始计算，生成采购清单和逐根切割示意。</p></section>
</div></template>
